import { useCallback, useRef, useState } from "react";
import { IconButton, Popover } from "@kit/index.js";
import { emitStepEvent, useTrack, useTranslation, useUser } from "travel-platform";
import "./catalog.js";
import { SignInPrompt } from "./SignInPrompt.jsx";
import styles from "./Wishlist.module.css";

export default function WishlistButton({ propertyId, name, saved, a11yLabel, overlay = true }) {
    const t = useTranslation();
    const track = useTrack();
    const user = useUser();
    const anchorRef = useRef(null);
    const [open, setOpen] = useState(false);
    const onClick = useCallback(() => {
        track("wishlist.click", { propertyId, loggedIn: user.loggedIn });
        if (!user.loggedIn) {
            setOpen(true);
            emitStepEvent("wishlist-prompt", { propertyId });
        }
    }, [track, propertyId, user.loggedIn]);
    const close = useCallback(() => setOpen(false), []);
    return (
        <span className={overlay ? styles.overlay : styles.inline}>
            <IconButton ref={anchorRef} icon={saved ? "heart" : "heart-outline"} label={a11yLabel ?? t("wl.save")} variant="tertiary-neutral" className={styles.button} onClick={onClick} aria-pressed={saved} data-testid="wishlist-button" />
            <Popover open={open} anchorRef={anchorRef} onClose={close} title={t("wl.prompt_title")} closeLabel={t("wl.close")} width={320} position="end" testId="wishlist-prompt">
                <SignInPrompt name={name} />
            </Popover>
        </span>
    );
}
